/* =========================================================
   ENTRADA: A.D.E. Y COLEGIO (VERSIÓN SENCILLA, SIN ANIMACIONES PESADAS)
   Qué hace: Muestra una introducción al abrir la página: ventana de bienvenida con el botón ¡Listo!, luego el logo de A.D.E., luego el logo del colegio José Joaquín Flórez Hernández, y al final se ve la página.
   Por qué: Da una bienvenida con la identidad del colegio. Solo hace falta este archivo, porque el logo de A.D.E. va dentro de él (por eso pesa más que los demás).
   Uso: <script src="js/entrada.js"></script>
   Sonido: al aparecer cada logo suena una moneda estilo videojuego retro, creada con código (no hace falta audio). Para quitarlo: SONIDO_MONEDA = false.
   Logo del colegio, en este orden: 1) SCHOOL_LOGO_SRC (ruta, ej. "img/colegio.png"); 2) si está vacío, la imagen con id="school" del index.html; 3) si no hay ninguna, solo se muestra el nombre.
   Saltar: botón "saltar" (abajo al centro) o Esc / Enter / espacio.
   Para repetirla desde un botón: reproducirIntro() (ahí no sale la ventana de ¡Listo!).
   Ajustes rápidos: SCHOOL_LOGO_SRC, SCHOOL_NAME, SHOW_MS, FADE_MS, ASK_READY.
   ========================================================= */

/* ---------- Envoltura del archivo ----------
   Qué hace: Encierra todo en una función que se ejecuta sola.
   Por qué: Así sus variables no se mezclan con las de otros archivos. */
(function(){

  /* ---------- Ajustes: cuándo se muestra ----------
     Qué hace: PLAY_ONLY_ONCE_PER_SESSION indica si solo se muestra una vez por sesión (ahora no), y ASK_READY si primero sale la ventana con el botón ¡Listo!.
     Por qué: El botón ¡Listo! sirve porque los navegadores solo dejan sonar audio después de un clic. */
  const PLAY_ONLY_ONCE_PER_SESSION = false;
  const ASK_READY = true;        // true = primero sale la ventana con el bot\u00f3n \u00a1Listo!

  /* ---------- Ajustes: logo y nombre del colegio ----------
     Qué hace: SCHOOL_LOGO_SRC es la ruta del logo (vacío = se busca solo) y SCHOOL_NAME el nombre que se muestra.
     Por qué: Son datos que pueden cambiar; están juntos y arriba para encontrarlos fácil. */
  const SCHOOL_LOGO_SRC = "img/icono-colegio.png";    // ruta del logo del colegio (vac\u00edo = se busca solo)
  const SCHOOL_NAME = "Colegio Jos\u00e9 Joaqu\u00edn Fl\u00f3rez Hern\u00e1ndez";

  /* ---------- Ajustes: tiempos ----------
     Qué hace: SHOW_MS es cuánto se queda cada logo, FADE_MS cuánto tarda en aparecer y desaparecer, y END_FADE_MS el desvanecido final hacia la página (todo en milisegundos).
     Por qué: Para hacerla más rápida o lenta basta con cambiar estos números. */
  const SHOW_MS = 2000;          // cu\u00e1nto se queda cada logo en pantalla (ms)
  const FADE_MS = 500;           // lo que tarda cada logo en aparecer y en desaparecer (ms)
  const END_FADE_MS = 450;       // desvanecido final hacia la p\u00e1gina (ms)

  /* ---------- Ajustes: sonido ----------
     Qué hace: SONIDO_MONEDA activa o quita la moneda, MONEDA_ARCHIVO permite usar un audio propio y MONEDA_VOLUMEN va de 0 a 1.
     Por qué: Por defecto el sonido se crea con código, sin necesidad de un archivo. */
  const SONIDO_MONEDA = true;    // true = suena la moneda cuando aparece el logo del colegio
  const MONEDA_ARCHIVO = "";     // opcional: ruta de un audio propio (ej. "sonido/moneda.mp3"); vac\u00edo = sonido creado por c\u00f3digo
  const MONEDA_VOLUMEN = 0.18;   // 0 a 1

  /* ---------- Logo de A.D.E. ----------
     Qué hace: Guarda la imagen del logo (PNG transparente) como un texto larguísimo dentro del archivo.
     Por qué: Así no hay que subir una imagen aparte. Esta línea es la que hace pesado al archivo: no hace falta leerla ni editarla. */
  // Logo A.D.E. sin fondo (PNG transparente)
  const LOGO_PNG = "data:image/png;base64,";

  /* ---------- Estilos de la entrada ----------
     Qué hace: Texto con los estilos (colores, tamaños y formas) de la ventana de entrada.
     Por qué: Se agregan desde aquí para no tocar el archivo de estilos. */
  const css = `
    #introEntrada{
      position:fixed; inset:0; z-index:2147483000; overflow:hidden;
      background:transparent;      /* se ve el fondo animado de la p\u00e1gina */
      font-family:Arimo,Arial,Helvetica,sans-serif;
    }
    #introEntrada.out{animation:inFadeOut ${END_FADE_MS}ms ease forwards}
    @keyframes inFadeOut{from{opacity:1}to{opacity:0}}

    /* ---- Mini ventana de bienvenida (antes de arrancar) ---- */
    #introEntrada .in-ready,#introEntrada .in-ready *{animation-play-state:running}
    #introEntrada .in-ready{
      position:absolute; inset:0; z-index:4; background:#000;
      display:flex; align-items:center; justify-content:center; padding:20px;
      transition:opacity .3s ease;
    }
    #introEntrada.started .in-ready{opacity:0;pointer-events:none}
    #introEntrada .in-win{
      width:min(560px,100%); max-height:100%; overflow:auto; text-align:center; color:#eafbf3;
      padding:clamp(24px,4.5vw,40px) clamp(20px,4.5vw,42px) clamp(22px,4vw,34px);
      border-radius:18px; border:1px solid rgba(35,160,90,.7);
      background:linear-gradient(165deg,rgba(11,58,77,.92),rgba(3,12,32,.95));
      box-shadow:0 0 40px rgba(35,160,90,.25), 0 0 70px rgba(51,222,142,.2), inset 0 0 30px rgba(51,222,142,.08);
      font-family:Arimo,Arial,Helvetica,sans-serif;
      animation:inReadyIn .6s ease both;
    }
    @keyframes inReadyIn{from{opacity:0;transform:translateY(14px) scale(.96)}to{opacity:1;transform:none}}
    #introEntrada .in-win-logo{
      display:block; width:clamp(150px,42vw,215px); height:auto; margin:0 auto 18px;
      filter:drop-shadow(0 0 1.5px #23c16b) drop-shadow(0 0 1.5px #23c16b) drop-shadow(0 0 16px rgba(46,230,160,.45));
    }
    #introEntrada .in-win h2{
      font-size:clamp(18px,5vw,24px); letter-spacing:1.5px; text-transform:uppercase; margin:0 0 10px;
      text-shadow:0 0 14px rgba(49,222,141,.6);
    }
    #introEntrada .in-win p{font-size:clamp(14px,3.8vw,16.5px); line-height:1.55; color:#b9cbe6; margin:0 0 16px}
    #introEntrada .in-win ul{list-style:none; margin:0 0 22px; padding:0; text-align:left; display:grid; gap:9px}
    #introEntrada .in-win li{
      display:flex; gap:12px; align-items:center; font-size:clamp(13px,3.5vw,15px); line-height:1.4; color:#d4ede1;
      padding:10px 12px; border-radius:10px; background:rgba(51,222,142,.1); border:1px solid rgba(104,231,172,.18);
    }
    #introEntrada .in-win li i{
      flex:none; width:38px; height:38px; border-radius:11px; display:grid; place-items:center;
      font-style:normal; color:#fff;
      background:linear-gradient(160deg,#2fb86d,#1d8a52); border:1px solid rgba(111,227,161,.55);
      box-shadow:inset 0 1px 0 rgba(255,255,255,.22), 0 4px 10px rgba(0,0,0,.3);
    }
    #introEntrada .in-win li i svg{width:21px; height:21px; display:block; fill:none; stroke:currentColor; stroke-width:1.9; stroke-linecap:round; stroke-linejoin:round}
    #introEntrada .in-win li b{color:#fff}
    #introEntrada .in-win-btn{
      width:100%; padding:16px 20px; border:0; border-radius:12px; cursor:pointer;
      background:linear-gradient(180deg,#2bb56d,#1c8c55); color:#fff;
      font:700 18px/1 Arimo,Arial,Helvetica,sans-serif; letter-spacing:1px;
      box-shadow:0 6px 18px rgba(35,160,90,.4);
      transition:transform .15s ease, filter .15s ease;
    }
    #introEntrada .in-win-btn:hover{filter:brightness(1.12);transform:translateY(-1px)}
    #introEntrada .in-win-btn:focus-visible{outline:2px solid rgba(125,255,192,.55);outline-offset:3px}


    #introEntrada .in-ready{background:transparent}

    /* ---- Escenario: un logo a la vez ---- */
    #introEntrada .in-stage{
      position:absolute; inset:0; z-index:2; display:grid; place-items:center; padding:24px;
      opacity:0; pointer-events:none; transition:opacity ${FADE_MS}ms ease;
    }
    #introEntrada .in-stage.show{opacity:1}
    #introEntrada .in-card{
      display:flex; flex-direction:column; align-items:center; gap:18px; text-align:center;
    }
    /* Sin caja blanca: cada logo va solo, con su contorno verde */
    #introEntrada .in-logobox{background:none; padding:0}
    #introEntrada .in-logobox img{
      display:block; width:min(62vw,380px); max-height:42vh; height:auto; object-fit:contain;
    }
    #introEntrada #introLogoAde{
      filter:drop-shadow(0 0 1.5px #23c16b) drop-shadow(0 0 1.5px #23c16b) drop-shadow(0 0 2px #23c16b) drop-shadow(0 0 22px rgba(35,193,107,.5));
    }
    #introEntrada #introLogoColegio{
      width:min(62vw,380px,42vh); aspect-ratio:1; border-radius:50%;
      box-shadow:0 0 0 5px #23c16b, 0 0 40px 8px rgba(35,193,107,.45), 0 12px 40px rgba(0,0,0,.45);
    }
    #introEntrada .in-caption{
      color:#eafbf3; font-weight:700; letter-spacing:1.2px; text-transform:uppercase;
      font-size:clamp(15px,4vw,22px); max-width:min(90vw,620px); line-height:1.35;
    }

    #introEntrada .in-skip{
      position:absolute; left:50%; bottom:22px; transform:translateX(-50%); z-index:3;
      padding:8px 12px; border:0; border-radius:0; background:none; box-shadow:none;
      color:rgba(212,248,231,.5); cursor:pointer;
      font:400 12px/1 Arimo,Arial,Helvetica,sans-serif; letter-spacing:2px; text-transform:lowercase;
      display:flex; align-items:center; gap:6px;
      -webkit-tap-highlight-color:transparent;
      transition:color .2s ease, opacity .5s ease;
      opacity:0; pointer-events:none;
    }
    /* el bot\u00f3n saltar aparece cuando se pulsa \u00a1Listo! */
    #introEntrada.go .in-skip{opacity:1; pointer-events:auto}
    #introEntrada .in-skip:hover{color:#7dffc0;text-decoration:underline;text-underline-offset:4px}
    #introEntrada .in-skip:focus-visible{outline:1px dashed rgba(255,255,255,.6);outline-offset:2px}
  `;

  /* ---------- Estructura de la entrada ----------
     Qué hace: Texto con las piezas que se dibujan: la etapa de A.D.E., la del colegio, la ventana ¡Listo! y el botón de saltar.
     Por qué: Se crean desde aquí para no tocar el HTML. */
  const html = `
  <div class="in-stage" id="introEtapaAde">
    <div class="in-card">
      <div class="in-logobox"><img id="introLogoAde" alt="A.D.E."></div>
      <div class="in-caption">Agenda Digital Escolar</div>
    </div>
  </div>

  <div class="in-stage" id="introEtapaColegio">
    <div class="in-card">
      <div class="in-logobox" id="introColegioBox"><img id="introLogoColegio" alt=""></div>
      <div class="in-caption" id="introColegioNombre"></div>
    </div>
  </div>

  <div class="in-ready">
    <div class="in-win" role="dialog" aria-label="Bienvenida">
      <img class="in-win-logo" id="introWinLogo" alt="A.D.E." width="412" height="265">
      <h2>Agenda Digital Escolar</h2>
      <p>Tu agenda escolar en un solo lugar. Organ\u00edzate mes a mes con:</p>
      <ul>
        <li><i><svg viewBox="0 0 24 24" aria-hidden="true"><rect x="5" y="4" width="14" height="17" rx="2.5"/><path d="M9 4h6v3H9z"/><path d="m8.4 12 1 1 2-2M13.6 12.3H16M8.4 17l1 1 2-2M13.6 17.3H16"/></svg></i><span><b>Actividades:</b> tareas por materia con fecha de entrega y archivos.</span></li>
        <li><i><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 6.8C10 5.2 7.3 4.6 3.8 4.8v13.4c3.5-.2 6.2.4 8.2 2 2-1.6 4.7-2.2 8.2-2V4.8c-3.5-.2-6.2.4-8.2 2z"/><path d="M12 6.8v13.4"/><path d="M6.5 9.4h2.6M6.5 12.4h2.6M14.9 9.4h2.6M14.9 12.4h2.6"/></svg></i><span><b>Materias:</b> todas las materias del colegio en un solo lugar.</span></li>
        <li><i><svg viewBox="0 0 24 24" aria-hidden="true"><rect x="3.5" y="5" width="17" height="15.5" rx="3"/><path d="M3.5 10h17M8 3v4M16 3v4"/><path d="M8 13.6h.01M12 13.6h.01M16 13.6h.01M8 17h.01M12 17h.01M16 17h.01" stroke-width="2.4"/></svg></i><span><b>Horario:</b> tus clases de la semana con su hora.</span></li>
        <li><i><svg viewBox="0 0 24 24" aria-hidden="true"><rect x="3.5" y="5" width="17" height="15.5" rx="3"/><path d="M3.5 10h17M8 3v4M16 3v4"/><path d="m9 15 2 2 4-4"/></svg></i><span><b>Calendario mensual:</b> eventos y fechas importantes del colegio.</span></li>
      </ul>
      <button class="in-win-btn" type="button">\u00a1Listo!</button>
    </div>
  </div>

  <button class="in-skip" aria-label="Saltar la entrada" title="Saltar">
    saltar
    <svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round">
      <path d="M5 4 L13 12 L5 20"/><path d="M13 4 L21 12 L13 20"/>
    </svg>
  </button>
  `;

  /* ---------- Sonido de moneda ----------
     Qué hace: Funciones que preparan y reproducen el sonido. Los navegadores solo dejan sonar audio después de un clic, por eso se prepara al pulsar ¡Listo! y suena más tarde, cuando aparece el logo.
     Por qué: Sin esta preparación, el sonido saldría bloqueado. */
  // ---- Sonido de moneda ----
  // Los navegadores solo dejan sonar audio despu\u00e9s de un toque o clic de la persona,
  // por eso el sonido se prepara al pulsar \u00a1Listo! y suena m\u00e1s tarde, cuando aparece el logo.

  /* ---------- Variables del sonido ----------
     Qué hace: Guardan el sistema de audio y el archivo de audio (si se usa uno propio). */
  let audioCtx = null;
  let audioArchivo = null;

  /* ---------- Preparar el sonido ----------
     Qué hace: Activa el audio (o carga el archivo propio) en el momento del clic.
     Por qué: Es el paso que permite que el sonido suene después. */
  function prepararSonido(){
    if(!SONIDO_MONEDA) return;
    try{
      if(MONEDA_ARCHIVO){
        audioArchivo = new Audio(MONEDA_ARCHIVO);
        audioArchivo.preload = "auto";
        audioArchivo.volume = 0;
        const p = audioArchivo.play();
        if(p && p.then) p.then(function(){ audioArchivo.pause(); audioArchivo.currentTime = 0; audioArchivo.volume = MONEDA_VOLUMEN; }).catch(function(){});
      }else{
        const AC = window.AudioContext || window.webkitAudioContext;
        if(AC){
          audioCtx = new AC();
          if(audioCtx.state === "suspended") audioCtx.resume();
        }
      }
    }catch(e){}
  }

  /* ---------- Sonar la moneda ----------
     Qué hace: Toca dos notas cortas de onda cuadrada (si agudo, luego mi más agudo que se apaga) que suenan a "moneda".
     Por qué: Se crea con código para no depender de un archivo de audio. */
  // Dos notas cortas de onda cuadrada (si agudo, luego mi m\u00e1s agudo que se apaga): suena a "moneda"
  function sonarMoneda(){
    if(!SONIDO_MONEDA) return;
    try{
      if(audioArchivo){
        audioArchivo.currentTime = 0;
        audioArchivo.volume = MONEDA_VOLUMEN;
        audioArchivo.play().catch(function(){});
        return;
      }
      if(!audioCtx) return;
      if(audioCtx.state === "suspended") audioCtx.resume();

      const t = audioCtx.currentTime;
      const master = audioCtx.createGain();
      master.gain.value = MONEDA_VOLUMEN;
      master.connect(audioCtx.destination);

      function nota(frecuencia, inicio, duracion){
        const osc = audioCtx.createOscillator();
        const g = audioCtx.createGain();
        osc.type = "square";
        osc.frequency.setValueAtTime(frecuencia, t + inicio);
        g.gain.setValueAtTime(0.0001, t + inicio);
        g.gain.exponentialRampToValueAtTime(1, t + inicio + 0.006);
        g.gain.exponentialRampToValueAtTime(0.0001, t + inicio + duracion);
        osc.connect(g);
        g.connect(master);
        osc.start(t + inicio);
        osc.stop(t + inicio + duracion + 0.03);
      }

      nota(987.77, 0, 0.09);       // Si5
      nota(1318.51, 0.09, 0.6);    // Mi6
    }catch(e){}
  }

  /* ---------- Buscar el logo del colegio ----------
     Qué hace: Usa la ruta escrita arriba o, si está vacía, la imagen id="school" de la página.
     Por qué: Si no encuentra ninguna, se muestra solo el nombre del colegio. */
  // Busca el logo del colegio: ruta escrita arriba, o la imagen id="school" de la p\u00e1gina
  function logoColegio(){
    if(SCHOOL_LOGO_SRC) return SCHOOL_LOGO_SRC;
    const el = document.getElementById("school");
    if(el && el.tagName === "IMG"){
      const s = el.currentSrc || el.getAttribute("src") || "";
      if(s) return s;
    }
    return "";
  }

  /* ---------- Reproducir la entrada ----------
     Qué hace: Arma la ventana, prepara las etapas, los tiempos, el botón ¡Listo!, la tecla para saltar y el cierre. force = true la reproduce siempre.
     Por qué: Es la función principal de este archivo. */
  function play(force){

    if(document.getElementById("introEntrada")) return;

    /* ---------- ¿Mostrar o no? ----------
       Qué hace: No se muestra si ya hay una sesión iniciada o si la persona pidió menos animaciones.
       Por qué: No hace falta repetirla a quien ya entró, y se respeta la preferencia de menos movimiento. */
    // Solo se muestra si la persona no tiene la sesi\u00f3n iniciada ni pidi\u00f3 menos animaciones
    if(!force){
      if(window.matchMedia && matchMedia("(prefers-reduced-motion: reduce)").matches) return;
      try{
        if(localStorage.getItem("ade_current_user")) return;
        if(PLAY_ONLY_ONCE_PER_SESSION){
          if(sessionStorage.getItem("ade_intro_seen")) return;
          sessionStorage.setItem("ade_intro_seen", "1");
        }
      }catch(e){}
    }

    const style = document.createElement("style");
    style.textContent = css;
    document.head.appendChild(style);

    /* ---------- Pausar la página ----------
       Qué hace: Detiene las animaciones de la página de inicio mientras se ve la entrada.
       Por qué: Para que no gasten recursos detrás. */
    // Mientras se ve la entrada, las animaciones de la p\u00e1gina de inicio no corren
    const hold = document.createElement("style");
    hold.id = "introHoldLanding";
    hold.textContent = "#landingScreen{visibility:hidden}#landingScreen *,#landingScreen *::before,#landingScreen *::after{animation:none !important}";
    document.head.appendChild(hold);

    const overlay = document.createElement("div");
    overlay.id = "introEntrada";
    overlay.innerHTML = html;
    document.body.appendChild(overlay);
    document.documentElement.style.overflow = "hidden";

    /* ---------- Preparar los logos ----------
       Qué hace: Busca las imágenes y pone el logo del colegio (o solo su nombre).
       Por qué: Cada etapa necesita su imagen lista antes de mostrarse. */
    // Logos
    const imgAde = overlay.querySelector("#introLogoAde");
    imgAde.src = LOGO_PNG;
    overlay.querySelector("#introWinLogo").src = LOGO_PNG;

    const etapaAde = overlay.querySelector("#introEtapaAde");
    const etapaCol = overlay.querySelector("#introEtapaColegio");
    const boxCol = overlay.querySelector("#introColegioBox");
    const imgCol = overlay.querySelector("#introLogoColegio");
    overlay.querySelector("#introColegioNombre").textContent = SCHOOL_NAME;

    const srcCol = logoColegio();
    if(srcCol){
      imgCol.alt = SCHOOL_NAME;
      imgCol.onerror = function(){ boxCol.style.display = "none"; };   // si no carga, queda solo el nombre
      imgCol.src = srcCol;
    }else{
      boxCol.style.display = "none";
    }

    let finished = false;
    let started = false;
    const timers = [];
    function later(fn, ms){ timers.push(setTimeout(fn, ms)); }

    const gate = ASK_READY && !force;
    const readyEl = overlay.querySelector(".in-ready");
    if(!gate && readyEl) readyEl.remove();

    /* ---------- Terminar ----------
       Qué hace: Quita la entrada y deja ver la página con un desvanecido suave.
       Por qué: Se llama al acabar o al saltar. */
    function end(){
      if(finished) return;
      finished = true;
      timers.forEach(clearTimeout);
      document.removeEventListener("keydown", onKey);
      if(audioCtx){ const ctx = audioCtx; setTimeout(function(){ try{ ctx.close(); }catch(e){} }, 1500); }
      overlay.classList.add("out");
      // La p\u00e1gina de inicio aparece suave mientras la entrada se va
      hold.textContent = "@keyframes inLandIn{from{opacity:0}to{opacity:1}}#landingScreen{animation:inLandIn " + END_FADE_MS + "ms ease both}";
      setTimeout(function(){
        hold.remove();
        overlay.remove();
        style.remove();
        document.documentElement.style.overflow = "";
      }, END_FADE_MS + 50);
    }

    /* ---------- Secuencia de logos ----------
       Qué hace: Muestra el logo de A.D.E., luego el del colegio, y al final la página, con sonido de moneda en cada logo.
       Por qué: Es el orden de la entrada. */
    // Logo de A.D.E. -> desaparece -> logo del colegio -> desaparece -> p\u00e1gina
    function start(){
      if(started || finished) return;
      started = true;
      overlay.classList.add("go");                       // ahora s\u00ed se muestra "saltar"
      prepararSonido();                                  // se hace aqu\u00ed porque viene de un clic en \u00a1Listo!

      if(readyEl && readyEl.parentNode){
        overlay.classList.add("started");
        later(function(){ if(readyEl.parentNode) readyEl.remove(); }, 400);
      }

      const t1 = gate ? 350 : 0;                         // espera a que se vaya la ventana
      later(function(){ etapaAde.classList.add("show"); sonarMoneda(); }, t1);
      later(function(){ etapaAde.classList.remove("show"); }, t1 + FADE_MS + SHOW_MS);
      const t2 = t1 + FADE_MS + SHOW_MS + FADE_MS;       // el segundo aparece cuando el primero ya se fue
      later(function(){ etapaCol.classList.add("show"); sonarMoneda(); }, t2);
      later(function(){ etapaCol.classList.remove("show"); }, t2 + FADE_MS + SHOW_MS);
      later(end, t2 + FADE_MS + SHOW_MS + FADE_MS);
    }

    /* ---------- Saltar con el teclado ----------
       Qué hace: Termina la entrada al presionar Esc, Enter o espacio.
       Por qué: Para quien no quiera esperar. */
    function onKey(e){
      if(e.key === "Escape"){ end(); return; }
      if(e.key === "Enter" || e.key === " "){
        // en la ventana, Enter / espacio pulsan \u00a1Listo!; ya en marcha, saltan la entrada
        if(gate && !started){ e.preventDefault(); start(); } else end();
      }
    }

    /* ---------- Botón ¡Listo! ----------
       Qué hace: Si hay botón, la secuencia empieza al hacer clic; si no, empieza sola.
       Por qué: El clic permite activar el sonido. */
    const readyBtn = overlay.querySelector(".in-win-btn");
    if(readyBtn) readyBtn.addEventListener("click", function(){ start(); });
    if(gate && readyBtn) readyBtn.focus();
    if(!gate) start();

    overlay.querySelector(".in-skip").addEventListener("click", function(e){
      e.stopPropagation();
      end();
    });
    document.addEventListener("keydown", onKey);
  }

  /* ---------- Repetir la entrada ----------
     Qué hace: Permite ejecutar la entrada desde cualquier botón con reproducirIntro() (sin ventana de ¡Listo!).
     Por qué: Por si se quiere volver a verla. */
  window.reproducirIntro = function(){ play(true); };

  /* ---------- Arranque ----------
     Qué hace: Reproduce la entrada apenas la página esté lista.
     Por qué: Si todavía no cargó, espera al evento DOMContentLoaded. */
  if(document.body) play(false);
  else document.addEventListener("DOMContentLoaded", function(){ play(false); });

})();